            if self.op == "ADD" and self.anchor_target:
                op["anchor"] = {"target": self.anchor_target, "position": self.anchor_position}
            if self.action == "追加操作":
                ops.append(op)
            else:
                if not 1 <= self.operation_number <= len(ops):
                    raise ValueError("操作编号超出当前候选范围")
                ops[self.operation_number - 1] = op
            if self.action == "修订操作与 P/V/I":
                pvi = {"P": [self.persistent_text] if self.persistent_text else [],
                       "V": [self.volatile_text] if self.volatile_text else [], "I": object_value(self.instant_views)}
        result = perform(self, "edit.candidate.update", {"job_id": job, "expected_revision": expected_revision,
                         "ops": ops, "pvi": pvi}, context=context)
        if result.get("ok"):
            result["presentation"] = {"submitted_ops": ops, "submitted_pvi": pvi,
                                      "original_responses_read_only": True, "old_validation_stale": True}
        return result

    def run_candidate(self) -> Data:
        return Data(data=cached(self, self._act))

    def operations(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        ops = result.get("ops", result.get("material", {}).get("ops", envelope.get("presentation", {}).get("submitted_ops", [])))
        return table([{"序号": i + 1, "记录下标": i, "操作": op.get("op"), "目标": text(op.get("target", op.get("targets", ""))),
                       "内容": op.get("content", ""), "内容生命周期": op.get("lifecycle", "P"), "风险": op.get("risk", "unknown"),
                       "理由": op.get("reason", ""), "来源": op.get("origin", op.get("editor", "候选提案")),
                       "候选版本": result.get("revision", self.expected_revision)} for i, op in enumerate(ops)])

    def lifecycles(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        pvi = result.get("pvi", envelope.get("presentation", {}).get("submitted_pvi", {}))
        material = result.get("material", {})
        if material:
            pvi = {"P": [material.get("body", "")], "V": material.get("volatile", []), "I": material.get("instant", {})}
        return table([{"生命周期": key, "去向": destination, "内容": text(pvi.get(key, {} if key == "I" else [])),
                       "旧CB可改": False} for key, destination in [("P", "本次CB固定"), ("V", "下一WB可再编辑"), ("I", "独立当前视图，不进入WB")]])

    def originals(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        original = getattr(self, "_candidate_original", None) or {}
        responses = original.get("original_responses", {})
        entries = responses.items() if isinstance(responses, dict) else enumerate(responses)
        return table([{"交付者": str(key), "原始交付（只读）": text(value), "人工修订是否冒充原始输出": False}
                      for key, value in entries])

import copy

from sic_workflow.workbench_component import WorkbenchComponent as Component
from lfx.io import BoolInput, CodeInput, DataInput, DropdownInput, IntInput, MultilineInput, StrInput, Output
from lfx.schema import Data, DataFrame
from sic_workflow.workbench_support import cached, context_of, error_rows, object_value, perform, reset, table, text


class SICCandidate(Component):
    display_name = "SIC 候选版本编辑"
    description = "修订尚未发布的op与P/V/I，保留模型原始交付；旧校验随版本失效。已发布CB与op不可改。R13–25/R61。"
    icon = "FilePenLine"
    name = "SICCandidate"
    inputs = [
        DataInput(name="previous", display_name="前一步", required=False),
        StrInput(name="chain_id", display_name="工作路线", value=""),
        StrInput(name="job_id", display_name="编辑任务", value=""),
        DropdownInput(name="action", display_name="候选操作", options=["读取候选", "追加操作", "修改一项操作", "修订操作与 P/V/I", "移除一项操作", "修改 P/V/I", "替换完整序列（高级）", "校验候选", "发布此版本"], value="读取候选", real_time_refresh=True),
        IntInput(name="expected_revision", display_name="已核对候选版本（-1沿用前一步）", value=0),
        IntInput(name="operation_number", display_name="修改/移除第几项（从1起）", value=1),
        DropdownInput(name="op", display_name="内容操作", options=["KEEP", "DELETE", "FLAG", "REORDER", "COMPRESS", "REPLACE", "ADD"], value="REPLACE"),
        StrInput(name="target", display_name="原文单元ID", value=""),
        MultilineInput(name="content", display_name="新正文或标记", value=""),
        MultilineInput(name="reason", display_name="编辑理由 / 信息损失说明", value=""),
        IntInput(name="order", display_name="重排位置", value=0),
        StrInput(name="anchor_target", display_name="ADD插入锚（可选）", value=""),
        DropdownInput(name="anchor_position", display_name="ADD锚位置", options=["before", "after"], value="after"),
        DropdownInput(name="lifecycle", display_name="生成内容的生命周期", options=["P", "V", "I"], value="P", info="操作账本本身始终持久；KEEP/DELETE/REORDER仅P。"),
        StrInput(name="view_key", display_name="I视图名称", value=""),
        DropdownInput(name="risk", display_name="信息损失风险", options=["none", "low", "medium", "high", "unknown"], value="unknown"),
        MultilineInput(name="persistent_text", display_name="P：本次固定内容", value="", info="空值表示此版本P为空；正文可含换行。"),
        MultilineInput(name="volatile_text", display_name="V：下一WB材料", value=""),
        CodeInput(name="instant_views", display_name="I：当前独立视图（JSON对象）", value="{}", info="不属于可编辑WB；下一覆写换版。决策四视角另有专门工作台。"),
        CodeInput(name="full_ops", display_name="完整候选op数组（高级）", value="[]", advanced=True),
        IntInput(name="expected_cut", display_name="已核对cut（-1沿用任务/前一步快照）", value=0),
        BoolInput(name="allow_write", display_name="允许本次修订/发布", value=False),
    ]
    outputs = [Output(name="result", display_name="候选 / 校验 / 发布结果", method="run_candidate", group_outputs=True),
               Output(name="operations", display_name="有序op与来源", method="operations", group_outputs=True),
               Output(name="originals", display_name="原始Editor交付（只读）", method="originals", group_outputs=True),
               Output(name="lifecycles", display_name="P / V / I去向", method="lifecycles", group_outputs=True)]
    for _field in inputs:
        if _field.name in {"operation_number", "op", "target", "content", "reason", "order", "anchor_target", "anchor_position", "lifecycle", "view_key", "risk", "persistent_text", "volatile_text", "instant_views", "full_ops", "expected_cut"}:
            _field.show = False

    def _pre_run_setup(self):
        reset(self)
        self._candidate_original = None

    def update_build_config(self, build_config, field_value, field_name=None):
        if field_name != "action":
            return build_config
        typed = field_value in {"追加操作", "修改一项操作", "修订操作与 P/V/I"}
        for key in ("op", "target", "content", "reason", "order", "anchor_target", "anchor_position", "lifecycle", "view_key", "risk"):
            build_config[key]["show"] = typed
        build_config["operation_number"]["show"] = field_value in {"修改一项操作", "修订操作与 P/V/I", "移除一项操作"}
        for key in ("persistent_text", "volatile_text", "instant_views"):
            build_config[key]["show"] = field_value in {"修改 P/V/I", "修订操作与 P/V/I"}
        build_config["full_ops"]["show"] = field_value == "替换完整序列（高级）"
        build_config["expected_cut"]["show"] = field_value == "发布此版本"
        return build_config

    def _act(self):
        context = context_of(self)
        job = self.job_id or context.get("job_id")
        if not job:
            return {"ok": False, "context": context, "error": {"code": "job_required", "message": "先选择已交付的编辑任务；不能以新空任务代替候选修订。"}}
        context["job_id"] = job
        original = perform(self, "edit.candidate.get", {"job_id": job}, context=context)
        if original.get("ok"):
            self._candidate_original = original["result"]
        if not original.get("ok") or self.action == "读取候选":
            return original
        candidate = original["result"]
        expected_revision = context.get("candidate_revision") if self.expected_revision == -1 else self.expected_revision
        if candidate["revision"] != expected_revision:
            return {"ok": False, "context": context, "error": {"code": "candidate_stale", "message": f"候选已是版本{candidate['revision']}，请重新读取；不自动覆盖。"}}
        if self.action == "校验候选":
            return perform(self, "edit.validate", {"job_id": job}, context=context)
        if self.action == "发布此版本":
            expected_cut = context.get('reviewed_cut') if self.expected_cut == -1 else self.expected_cut
            if expected_cut is None:
                return {'ok': False, 'context': context, 'error': {'code': 'cut_snapshot_required', 'message': 'Prepare/read the job or explicitly supply its reviewed cut; no blind latest-version overwrite.'}}
            return perform(self, "cut.publish", {"job_id": job, "expected_cut": expected_cut,
                           "expected_candidate_revision": expected_revision,
                           "idempotency_key": f"{job}:candidate:{expected_revision}"}, context=context)
        ops, pvi = copy.deepcopy(candidate["ops"]), copy.deepcopy(candidate.get("pvi", {}))
        if self.action == "修改 P/V/I":
            pvi = {"P": [self.persistent_text] if self.persistent_text else [],
                   "V": [self.volatile_text] if self.volatile_text else [], "I": object_value(self.instant_views)}
        elif self.action == "替换完整序列（高级）":
            ops = object_value(self.full_ops, list)
        elif self.action == "移除一项操作":
            if not 1 <= self.operation_number <= len(ops):
                raise ValueError("操作编号超出当前候选范围")
            ops.pop(self.operation_number - 1)
        else:
            op = {"op": self.op}
            op["lifecycle"] = self.lifecycle
            op["risk"] = self.risk
            if self.lifecycle == "I":
                op["view_key"] = self.view_key
            if self.op != "ADD":
                op["target"] = self.target
            if self.op in {"FLAG", "COMPRESS", "REPLACE", "ADD"}:
                op["content"] = self.content
            if self.reason:
                op["reason"] = self.reason
            if self.op == "REORDER":
                op["order"] = self.order
            if self.op == "ADD" and self.anchor_target:
                op["anchor"] = {"target": self.anchor_target, "position": self.anchor_position}
            if self.action == "追加操作":
                ops.append(op)
            else:
                if not 1 <= self.operation_number <= len(ops):
                    raise ValueError("操作编号超出当前候选范围")
                ops[self.operation_number - 1] = op
            if self.action == "修订操作与 P/V/I":
                pvi = {"P": [self.persistent_text] if self.persistent_text else [],
                       "V": [self.volatile_text] if self.volatile_text else [], "I": object_value(self.instant_views)}
        result = perform(self, "edit.candidate.update", {"job_id": job, "expected_revision": expected_revision,
                         "ops": ops, "pvi": pvi}, context=context)
        if result.get("ok"):
            result["presentation"] = {"submitted_ops": ops, "submitted_pvi": pvi,
                                      "original_responses_read_only": True, "old_validation_stale": True}
        return result

    def run_candidate(self) -> Data:
        return Data(data=cached(self, self._act))

    def operations(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        ops = result.get("ops", result.get("material", {}).get("ops", envelope.get("presentation", {}).get("submitted_ops", [])))
        return table([{"序号": i + 1, "记录下标": i, "操作": op.get("op"), "目标": text(op.get("target", op.get("targets", ""))),
                       "内容": op.get("content", ""), "内容生命周期": op.get("lifecycle", "P"), "风险": op.get("risk", "unknown"),
                       "理由": op.get("reason", ""), "来源": op.get("origin", op.get("editor", "候选提案")),
                       "候选版本": result.get("revision", self.expected_revision)} for i, op in enumerate(ops)])

    def lifecycles(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        pvi = result.get("pvi", envelope.get("presentation", {}).get("submitted_pvi", {}))
        material = result.get("material", {})
        if material:
            pvi = {"P": [material.get("body", "")], "V": material.get("volatile", []), "I": material.get("instant", {})}
        return table([{"生命周期": key, "去向": destination, "内容": text(pvi.get(key, {} if key == "I" else [])),
                       "旧CB可改": False} for key, destination in [("P", "本次CB固定"), ("V", "下一WB可再编辑"), ("I", "独立当前视图，不进入WB")]])

    def originals(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        original = getattr(self, "_candidate_original", None) or {}
        responses = original.get("original_responses", {})
        entries = responses.items() if isinstance(responses, dict) else enumerate(responses)
        return table([{"交付者": str(key), "原始交付（只读）": text(value), "人工修订是否冒充原始输出": False}
                      for key, value in entries])

from sic_workflow.workbench_component import WorkbenchComponent as Component
from lfx.io import DataInput, DropdownInput, IntInput, StrInput, Output
from lfx.schema import Data, DataFrame
from sic_workflow.workbench_support import cached, context_of, error_rows, perform, reset, table, text


class SICMemory(Component):
    display_name = "SIC 时序、来源与片段导航"
    description = "分别沿CB生成时序和CB↔WB来源导航，再读原文/正文/op片段；有限投影明确列未读档案。R18/R29–34。"
    icon = "LibraryBig"
    name = "SICMemory"
    inputs = [DataInput(name="previous", display_name="前一步", required=False),
              StrInput(name="chain_id", display_name="工作路线", value=""),
              DropdownInput(name="action", display_name="导航方向", options=["CB形成时序", "从WB找CB", "从CB找WB", "读取原文片段", "读取媒体原档片段", "读取通信来源片段", "读取冻结前缀计划", "读取实际模型请求", "读取固定CB片段", "读取持久op片段", "读取原始提案与修订链", "读取历史I片段", "有限背景投影"], value="CB形成时序", real_time_refresh=True),
              DropdownInput(name="cb_id", display_name="固定CB（刷新当前时序页）", options=[""], value="", refresh_button=True, combobox=True),
              DropdownInput(name="source_id", display_name="来源WB（刷新当前时序页）", options=[""], value="", refresh_button=True, combobox=True),
              StrInput(name="cut_id", display_name="历史I所属cut", value=""),
              StrInput(name="prefix_plan_id", display_name="冻结计划ID（只读；来自配置/Editor任务）", value=""),
              StrInput(name="provider_request_id", display_name="实际请求ID（只读；非准备计划）", value=""),
              StrInput(name="communication_id", display_name="通信来源WB / 快照cut（空读当前cut）", value="", info="只读来源、首次接收时点和收据；不是信箱消息ID。"),
              DropdownInput(name='view_scope', display_name='I读取范围', options=['当前cut默认','指定内部上下文/阶次','历史角色选择'],value='当前cut默认'),
              StrInput(name='context_id',display_name='I内部上下文',value='main'),
              IntInput(name='level',display_name='I阶次',value=1),
              StrInput(name='view_role',display_name='历史角色选择（如editor:alpha）',value='editor'),
              IntInput(name="offset", display_name="起始位置 / 记录下标", value=0),
              IntInput(name="timeline_size", display_name="本页时序条目（最多100）", value=20),
              IntInput(name="page_size", display_name="片段字符预算（最多8192）", value=2048),
              DropdownInput(name="role", display_name="投影供谁读取", options=["worker", "editor"], value="worker"),
              IntInput(name="max_chars", display_name="投影字符预算", value=4096),
              StrInput(name="query", display_name="优先查找线索", value="")]
    outputs = [Output(name="result", display_name="导航结果与可继续位置", method="navigate", group_outputs=True),
               Output(name="records", display_name="时序 / 对应 / 片段表", method="records", group_outputs=True)]

    def _pre_run_setup(self):
        reset(self)

    def update_build_config(self, build_config, field_value, field_name=None):
        if field_name == "action":
            visible = {"CB形成时序": {"offset", "timeline_size"}, "从WB找CB": {"source_id"}, "从CB找WB": {"cb_id"},
                       "读取冻结前缀计划": {"prefix_plan_id", "offset", "page_size"}, "读取实际模型请求": {"provider_request_id", "offset", "page_size"}, "读取原文片段": {"source_id", "offset", "page_size"}, "读取媒体原档片段": {"source_id", "offset", "page_size"}, "读取通信来源片段": {"communication_id", "offset", "page_size"}, "读取固定CB片段": {"cb_id", "offset", "page_size"},
                       "读取持久op片段": {"cb_id", "offset", "page_size"}, "读取原始提案与修订链": {"cb_id", "offset", "page_size"}, "读取历史I片段": {"cut_id", "offset", "page_size"},
                       "有限背景投影": {"role", "max_chars", "query"}}[field_value]
            if field_value=='读取历史I片段':visible |= {'view_scope','context_id','level','view_role'}
            for key in ("source_id", "cb_id", "cut_id", "communication_id", "prefix_plan_id", "provider_request_id", "offset", "timeline_size", "page_size", "role", "max_chars", "query",'view_scope','context_id','level','view_role'):
                build_config[key]["show"] = key in visible
            build_config["offset"]["display_name"] = "路线条目起点" if field_value == "CB形成时序" else "字符起点（按返回unit）"
        if field_name in {"source_id", "cb_id"}:
            page = perform(self, "memory.timeline", {"offset": self.offset, "limit": min(self.timeline_size, 100)})
            if page.get("ok"):
                rows = page["result"]["rows"]
                build_config["cb_id"]["options"] = [""] + [row["cb_id"] for row in rows]
                build_config["source_id"]["options"] = [""] + list(dict.fromkeys(source for row in rows for source in row["source_ids"]))
        return build_config

    def _act(self):
        context = context_of(self)
        source_id = self.source_id or context.get("source_id")
        cb_id = self.cb_id or context.get("cb_id")
        if self.action == "CB形成时序":
            operation, payload = "memory.timeline", {"offset": self.offset, "limit": self.timeline_size}
        elif self.action in {"从WB找CB", "从CB找WB"}:
            operation = "memory.locate"
            payload = {"source_id": source_id} if self.action == "从WB找CB" else {"cb_id": cb_id}
        elif self.action == "有限背景投影":
            operation, payload = "memory.project", {"role": self.role, "max_chars": self.max_chars, "query": self.query}
        elif self.action in {"读取冻结前缀计划", "读取实际模型请求"}:
            kind = "prefix_plan" if self.action == "读取冻结前缀计划" else "provider_request"
            object_id = self.prefix_plan_id if kind == "prefix_plan" else self.provider_request_id
            operation, payload = "memory.page", {"kind": kind, "object_id": object_id, "offset": self.offset, "limit": self.page_size}
        elif self.action == "读取通信来源片段":
            object_id = self.communication_id or context.get('cut_id')
            if not object_id:
                current = perform(self, 'chain.get', context=context)
                if not current.get('ok'):
                    return current
                object_id = current['result'].get('current_cut')
            if not object_id:
                return {'ok': False, 'context': context, 'error': {'code': 'cut_required', 'message': '尚无固定cut；也可明确选择通信来源WB。'}}
            operation, payload = 'memory.page', {'kind': 'communication', 'object_id': object_id, 'offset': self.offset, 'limit': self.page_size}
        else:
            kind = {"读取原文片段": "source", "读取媒体原档片段": "media", "读取固定CB片段": "cb", "读取持久op片段": "ops", "读取原始提案与修订链": "proposal", "读取历史I片段": "view"}[self.action]
            object_id = source_id if kind in {"source", "media"} else (self.cut_id or context.get("cut_id")) if kind == "view" else cb_id
            operation, payload = "memory.page", {"kind": kind, "object_id": object_id, "offset": self.offset, "limit": self.page_size}
            if kind=='view':
                if self.view_scope=='指定内部上下文/阶次':payload.update(context_id=self.context_id,level=self.level)
                elif self.view_scope=='历史角色选择':payload['role']=self.view_role
        return perform(self, operation, payload, context=context)

    def navigate(self) -> Data:
        return Data(data=cached(self, self._act))

    def records(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        if envelope["operation"] == "memory.timeline":
            return table([{"当前路线位置": row["membership_index"], "固定CB": row["cb_id"], "原形成路线": row["formed_on_chain"],
                           "原形成顺序": row["original_sequence"], "前一CB": row["predecessor"], "后一CB": row["successor"],
                           "WB": row.get("wb_id"), "来源": text(row["source_ids"]), "正文线索": row["excerpt"],
                           "下页起点": result.get("next_offset")} for row in result["rows"]])
        if envelope["operation"] == "memory.locate":
            rows = []
            for row in result["rows"]:
                for unit in row.get("unit_index", []) or [{}]:
                    rows.append({"固定CB": row["cb_id"], "WB": row.get("wb_id"), "来源": text(row["source_ids"]),
                                 "路线内位置": row["membership_index"], "源单元": unit.get("unit_id"), "源锚": text(unit.get("anchor", {})),
                                 "对应op下标": text(unit.get("operation_indexes", [])), "总op数": row["operation_count"], "待发布": result.get("pending", False)})
            return table(rows)
        if envelope["operation"] == "memory.page":
            value = result["value"]
            if result["kind"] == "ops" and isinstance(value, list):
                rows = [{"记录下标": result["offset"] + i, "操作": op.get("op"), "目标": text(op.get("target", op.get("targets", ""))),
                         "内容": op.get("content", ""), "锚": text(op.get("anchor", {})), "来源": op.get("origin", op.get("editor", "")),
                         "不可变": True, "完整摘要": result["full_digest"], "下页起点": result.get("next_offset")} for i, op in enumerate(value)]
            else:
                rows = [{"对象": result["object_id"], "种类": result["kind"], "起点": result["offset"], "计数单位": result["unit"],
                         "完整长度": result["total"], "片段正文（只读）": value, "完整摘要": result["full_digest"], "下页起点": result.get("next_offset")}]
            return table(rows)
        manifest = result["manifest"]
        rows = [{"固定CB": cb["cb_id"], "本次读到的正文": cb["body"], "本次op数": len(cb["ops"]),
                 "档案导航": text(cb.get("archive_navigation", {})), "策略": manifest["policy"], "角色": manifest["role"]} for cb in result["cbs"]]
        rows.append({"固定CB": "未读档案 / 继续导航", "本次读到的正文": "未读不是已读；原始固定档案不改写", "策略": manifest["policy"],
                     "角色": manifest["role"], "档案导航": text({key: manifest[key] for key in ("archive_count", "omitted_count", "fragment_cb_ids", "max_chars", "presented_chars", "navigation")})})
        if manifest.get('legacy_unindexed_count',0):
            rows.append({'固定CB':'旧档案索引状态','旧档案数量':manifest['legacy_unindexed_count'],'WB形成顺序':'unknown',
                         '档案导航':text(manifest.get('legacy_unindexed_navigation',{})),'说明':'未保存层级/时序不补造；已知CB顺序与原WB/source仍可读取'})
        return table(rows)

from sic_workflow.workbench_component import WorkbenchComponent as Component
from lfx.io import DataInput, DropdownInput, IntInput, StrInput, Output
from lfx.schema import Data, DataFrame
from sic_workflow.workbench_support import cached, context_of, error_rows, perform, reset, table, text


class SICMemory(Component):
    display_name = "SIC 时序、来源与片段导航"
    description = "分别沿CB生成时序和CB↔WB来源导航，再读原文/正文/op片段；有限投影明确列未读档案。R18/R29–34。"
    icon = "LibraryBig"
    name = "SICMemory"
    inputs = [DataInput(name="previous", display_name="前一步", required=False),
              StrInput(name="chain_id", display_name="工作路线", value=""),
              DropdownInput(name="action", display_name="导航方向", options=["CB形成时序", "从WB找CB", "从CB找WB", "读取原文片段", "读取媒体原档片段", "读取通信来源片段", "读取冻结前缀计划", "读取实际模型请求", "读取固定CB片段", "读取持久op片段", "读取原始提案与修订链", "读取历史I片段", "有限背景投影"], value="CB形成时序", real_time_refresh=True),
              DropdownInput(name="cb_id", display_name="固定CB（刷新当前时序页）", options=[""], value="", refresh_button=True, combobox=True),
              DropdownInput(name="source_id", display_name="来源WB（刷新当前时序页）", options=[""], value="", refresh_button=True, combobox=True),
              StrInput(name="cut_id", display_name="历史I所属cut", value=""),
              StrInput(name="prefix_plan_id", display_name="冻结计划ID（只读；来自配置/Editor任务）", value=""),
              StrInput(name="provider_request_id", display_name="实际请求ID（只读；非准备计划）", value=""),
              StrInput(name="communication_id", display_name="通信来源WB / 快照cut（空读当前cut）", value="", info="只读来源、首次接收时点和收据；不是信箱消息ID。"),
              DropdownInput(name='view_scope', display_name='I读取范围', options=['当前cut默认','指定内部上下文/阶次','历史角色选择'],value='当前cut默认'),
              StrInput(name='context_id',display_name='I内部上下文',value='main'),
              IntInput(name='level',display_name='I阶次',value=1),
              StrInput(name='view_role',display_name='历史角色选择（如editor:alpha）',value='editor'),
              IntInput(name="offset", display_name="起始位置 / 记录下标", value=0),
              IntInput(name="timeline_size", display_name="本页时序条目（最多100）", value=20),
              IntInput(name="page_size", display_name="片段字符预算（最多8192）", value=2048),
              DropdownInput(name="role", display_name="投影供谁读取", options=["worker", "editor"], value="worker"),
              IntInput(name="max_chars", display_name="投影字符预算", value=4096),
              StrInput(name="query", display_name="优先查找线索", value="")]
    outputs = [Output(name="result", display_name="导航结果与可继续位置", method="navigate", group_outputs=True),
               Output(name="records", display_name="时序 / 对应 / 片段表", method="records", group_outputs=True)]

    def _pre_run_setup(self):
        reset(self)

    def update_build_config(self, build_config, field_value, field_name=None):
        if field_name == "action":
            visible = {"CB形成时序": {"offset", "timeline_size"}, "从WB找CB": {"source_id"}, "从CB找WB": {"cb_id"},
                       "读取冻结前缀计划": {"prefix_plan_id", "offset", "page_size"}, "读取实际模型请求": {"provider_request_id", "offset", "page_size"}, "读取原文片段": {"source_id", "offset", "page_size"}, "读取媒体原档片段": {"source_id", "offset", "page_size"}, "读取通信来源片段": {"communication_id", "offset", "page_size"}, "读取固定CB片段": {"cb_id", "offset", "page_size"},
                       "读取持久op片段": {"cb_id", "offset", "page_size"}, "读取原始提案与修订链": {"cb_id", "offset", "page_size"}, "读取历史I片段": {"cut_id", "offset", "page_size"},
                       "有限背景投影": {"role", "max_chars", "query"}}[field_value]
            if field_value=='读取历史I片段':visible |= {'view_scope','context_id','level','view_role'}
            for key in ("source_id", "cb_id", "cut_id", "communication_id", "prefix_plan_id", "provider_request_id", "offset", "timeline_size", "page_size", "role", "max_chars", "query",'view_scope','context_id','level','view_role'):
                build_config[key]["show"] = key in visible
            build_config["offset"]["display_name"] = "路线条目起点" if field_value == "CB形成时序" else "字符起点（按返回unit）"
        if field_name in {"source_id", "cb_id"}:
            page = perform(self, "memory.timeline", {"offset": self.offset, "limit": min(self.timeline_size, 100)})
            if page.get("ok"):
                rows = page["result"]["rows"]
                build_config["cb_id"]["options"] = [""] + [row["cb_id"] for row in rows]
                build_config["source_id"]["options"] = [""] + list(dict.fromkeys(source for row in rows for source in row["source_ids"]))
        return build_config

    def _act(self):
        context = context_of(self)
        source_id = self.source_id or context.get("source_id")
        cb_id = self.cb_id or context.get("cb_id")
        if self.action == "CB形成时序":
            operation, payload = "memory.timeline", {"offset": self.offset, "limit": self.timeline_size}
        elif self.action in {"从WB找CB", "从CB找WB"}:
            operation = "memory.locate"
            payload = {"source_id": source_id} if self.action == "从WB找CB" else {"cb_id": cb_id}
        elif self.action == "有限背景投影":
            operation, payload = "memory.project", {"role": self.role, "max_chars": self.max_chars, "query": self.query}
        elif self.action in {"读取冻结前缀计划", "读取实际模型请求"}:
            kind = "prefix_plan" if self.action == "读取冻结前缀计划" else "provider_request"
            object_id = self.prefix_plan_id if kind == "prefix_plan" else self.provider_request_id
            operation, payload = "memory.page", {"kind": kind, "object_id": object_id, "offset": self.offset, "limit": self.page_size}
        elif self.action == "读取通信来源片段":
            object_id = self.communication_id or context.get('cut_id')
            if not object_id:
                current = perform(self, 'chain.get', context=context)
                if not current.get('ok'):
                    return current
                object_id = current['result'].get('current_cut')
            if not object_id:
                return {'ok': False, 'context': context, 'error': {'code': 'cut_required', 'message': '尚无固定cut；也可明确选择通信来源WB。'}}
            operation, payload = 'memory.page', {'kind': 'communication', 'object_id': object_id, 'offset': self.offset, 'limit': self.page_size}
        else:
            kind = {"读取原文片段": "source", "读取媒体原档片段": "media", "读取固定CB片段": "cb", "读取持久op片段": "ops", "读取原始提案与修订链": "proposal", "读取历史I片段": "view"}[self.action]
            object_id = source_id if kind in {"source", "media"} else (self.cut_id or context.get("cut_id")) if kind == "view" else cb_id
            operation, payload = "memory.page", {"kind": kind, "object_id": object_id, "offset": self.offset, "limit": self.page_size}
            if kind=='view':
                if self.view_scope=='指定内部上下文/阶次':payload.update(context_id=self.context_id,level=self.level)
                elif self.view_scope=='历史角色选择':payload['role']=self.view_role
        return perform(self, operation, payload, context=context)

    def navigate(self) -> Data:
        return Data(data=cached(self, self._act))

    def records(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        if envelope["operation"] == "memory.timeline":
            return table([{"当前路线位置": row["membership_index"], "固定CB": row["cb_id"], "原形成路线": row["formed_on_chain"],
                           "原形成顺序": row["original_sequence"], "前一CB": row["predecessor"], "后一CB": row["successor"],
                           "WB": row.get("wb_id"), "来源": text(row["source_ids"]), "正文线索": row["excerpt"],
                           "下页起点": result.get("next_offset")} for row in result["rows"]])
        if envelope["operation"] == "memory.locate":
            rows = []
            for row in result["rows"]:
                for unit in row.get("unit_index", []) or [{}]:
                    rows.append({"固定CB": row["cb_id"], "WB": row.get("wb_id"), "来源": text(row["source_ids"]),
                                 "路线内位置": row["membership_index"], "源单元": unit.get("unit_id"), "源锚": text(unit.get("anchor", {})),
                                 "对应op下标": text(unit.get("operation_indexes", [])), "总op数": row["operation_count"], "待发布": result.get("pending", False)})
            return table(rows)
        if envelope["operation"] == "memory.page":
            value = result["value"]
            if result["kind"] == "ops" and isinstance(value, list):
                rows = [{"记录下标": result["offset"] + i, "操作": op.get("op"), "目标": text(op.get("target", op.get("targets", ""))),
                         "内容": op.get("content", ""), "锚": text(op.get("anchor", {})), "来源": op.get("origin", op.get("editor", "")),
                         "不可变": True, "完整摘要": result["full_digest"], "下页起点": result.get("next_offset")} for i, op in enumerate(value)]
            else:
                rows = [{"对象": result["object_id"], "种类": result["kind"], "起点": result["offset"], "计数单位": result["unit"],
                         "完整长度": result["total"], "片段正文（只读）": value, "完整摘要": result["full_digest"], "下页起点": result.get("next_offset")}]
            return table(rows)
        manifest = result["manifest"]
        rows = [{"固定CB": cb["cb_id"], "本次读到的正文": cb["body"], "本次op数": len(cb["ops"]),
                 "档案导航": text(cb.get("archive_navigation", {})), "策略": manifest["policy"], "角色": manifest["role"]} for cb in result["cbs"]]
        rows.append({"固定CB": "未读档案 / 继续导航", "本次读到的正文": "未读不是已读；原始固定档案不改写", "策略": manifest["policy"],
                     "角色": manifest["role"], "档案导航": text({key: manifest[key] for key in ("archive_count", "omitted_count", "fragment_cb_ids", "max_chars", "presented_chars", "navigation")})})
        if manifest.get('legacy_unindexed_count',0):
            rows.append({'固定CB':'旧档案索引状态','旧档案数量':manifest['legacy_unindexed_count'],'WB形成顺序':'unknown',
                         '档案导航':text(manifest.get('legacy_unindexed_navigation',{})),'说明':'未保存层级/时序不补造；已知CB顺序与原WB/source仍可读取'})
        return table(rows)

import json
from pathlib import Path
import sys

from sic_workflow.workbench_component import WorkbenchComponent as Component
from lfx.io import BoolInput, CodeInput, DataInput, DropdownInput, StrInput, Output
from lfx.schema import Data, DataFrame
from sic_workflow.workbench_support import cached, context_of, error_rows, object_value, perform, reset, table, text
from sic_workflow.accounting_scope import ledger_payload,ledger_tables


class SICAccounting(Component):
    display_name = "SIC 调用账与条件费用对照"
    description = "单链或明确任务范围的真实总账。task只递归已记录协作分支及补充路线，不自动抓所有Agent；全任务交集可能跨路线，不代表同Agent免费窗口。"
    icon = "ChartNoAxesCombined"
    name = "SICAccounting"
    inputs = [DataInput(name="previous", display_name="前一步", required=False),
              StrInput(name="chain_id", display_name="当前路线", value=""),
              DropdownInput(name="scope", display_name="账务范围", options=["chain","task"], value="chain", info="task包含根链已记录协作分支及明确补充路线，不自动选择所有Agent。"),
              CodeInput(name="additional_chain_ids", display_name="明确补充的路线ID数组", value="[]"),
              CodeInput(name="prices_by_chain", display_name="任务各链版本化费率（路线ID→费率数组）", value="{}"),
              CodeInput(name="task_interval", display_name="实际任务区间 [开始秒,结束秒]；未知 []", value="[]"),
              DropdownInput(name="action", display_name="账目动作", options=["读取完整调用账", "两路线账面对照", "读取独立核验实验", "记录资源测量"], value="读取完整调用账"),
              StrInput(name="baseline_chain", display_name="基线路线", value=""),
              StrInput(name="sic_chain", display_name="SIC路线", value=""),
              StrInput(name="run_directory", display_name="已完成实验的项目相对目录", value="", info="先由独立validator核SHA和两臂不变量，再读对照；不执行模型。"),
              CodeInput(name="prices", display_name="版本化费率（数组，可空）", value="[]", advanced=True),
              StrInput(name="record_id", display_name="测量记录ID（重送沿用）", value="measurement-1"),
              DropdownInput(name="resource", display_name="实测资源", options=["program", "storage", "other-service"], value="program"),
              StrInput(name="quantity", display_name="实际测量用量（十进制）", value="0"),
              StrInput(name="unit", display_name="测量单位", value="cpu-second"),
              StrInput(name="measurement_method", display_name="测量方法与范围", value=""),
              StrInput(name="unit_price", display_name="单价（未知留空）", value=""),
              StrInput(name="currency", display_name="币种（未知留空）", value=""),
              StrInput(name="price_version", display_name="价格版本/来源", value=""),
              BoolInput(name="allow_write", display_name="允许记录本次实测资源", value=False)]
    outputs = [Output(name="result", display_name="核心账 / 独立核验对照", method="run_accounting", group_outputs=True),
               Output(name="charges", display_name="调用 / 资源 / 费率明细", method="charges", group_outputs=True),
               Output(name="unknowns", display_name="总账、时间与未定项", method="unknowns", group_outputs=True)]
    outputs += [Output(name="scope_details",display_name="范围 / 链价 / 角色阶次",method="scope_details",group_outputs=True),
                Output(name="timing_details",display_name="全任务与同链区间（分别展示）",method="timing_details",group_outputs=True)]

    def _pre_run_setup(self):
        reset(self)

    def set(self,**kwargs):
        unknown=set(kwargs)-{item.name for item in self.inputs}
        if unknown:raise KeyError('Unknown accounting input field: '+', '.join(sorted(unknown)))
        return super().set(**kwargs)

    def _act(self):
        context = context_of(self)
        if self.action == "读取独立核验实验":
            import sic_workflow
            project = Path(sic_workflow.__file__).resolve().parents[2]
            relative = Path(self.run_directory)
            if not self.run_directory or relative.is_absolute() or ".." in relative.parts:
                return {"ok": False, "context": context, "error": {"code": "relative_run_required", "message": "请选择项目内相对run目录，不接受任意绝对路径或上溯。"}}
            directory = (project / relative).resolve()
            directory.relative_to(project)
            scripts = str(project / "scripts")
            if scripts not in sys.path:
                sys.path.insert(0, scripts)
            from verify_v2_experiment import validate_run
            verified = validate_run(directory)
            if verified["status"] != "passed":
                return {"ok": False, "context": context, "error": {"code": "experiment_incomplete", "message": "仅有失败工件；不能显示为完整比较。"}}
            comparison = json.loads((directory / "comparison.json").read_text(encoding="utf-8"))
            return {"ok": True, "operation": "accounting.verified_artifact", "context": context, "result": comparison,
                    "verification": verified, "evidence": {"source": "independent-run-validator", "quality": "not_evaluated"}}
        payload=ledger_payload({'scope':self.scope,'prices':object_value(self.prices,list),'additional_chain_ids':object_value(self.additional_chain_ids,list),'prices_by_chain':object_value(self.prices_by_chain,dict),'task_interval':object_value(self.task_interval,list)})
        if self.action == "两路线账面对照":
            if self.scope!='chain':raise ValueError('两路线账面对照分别取单链；任务总账请按各根路线分别读取，不能暗中合并补充范围。')
            from sic_core.accounting import compare_workflows
            baseline = perform(self, "ledger.export", payload, context={**context, "chain_id": self.baseline_chain})
            if not baseline.get("ok"):
                return baseline
            sic = perform(self, "ledger.export", payload, context={**context, "chain_id": self.sic_chain})
            if not sic.get("ok"):
                return sic
            comparison = compare_workflows(baseline["result"]["summary"], sic["result"]["summary"])
            return {"ok": True, "operation": "accounting.route_comparison", "context": context, "result": comparison,
                    "evidence": {"source": "core-ledger-and-accounting", "paired_task_verified": False,
                                 "boundary": "两条路线的账面对照本身不证明同任务/同配置研究收益"}}
        if self.action == "记录资源测量":
            record = {"record_id": self.record_id, "resource": self.resource, "quantity": self.quantity,
                      "unit": self.unit, "measurement_method": self.measurement_method}
            if self.unit_price:
                record.update(unit_price=self.unit_price, currency=self.currency, price_version=self.price_version)
            saved = perform(self, "resource.record", record, context=context)
            if not saved.get("ok"):
                return saved
        return perform(self, "ledger.export", payload, context=context)

    def run_accounting(self) -> Data:
        return Data(data=cached(self, self._act))

    @staticmethod
    def _summaries(result):
        if "baseline" in result and "sic" in result:
            return [("baseline", result["baseline"]), ("sic", result["sic"])]
        return [("current", result.get("summary", result))]

    def charges(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        rows = []
        for arm, summary in self._summaries(envelope["result"]):
            for item in summary.get("rows", []) + summary.get("resource_rows", []):
                rows.append({"工作流": arm, "调用/测量": item.get("call_id") or item.get("record_id"), "角色/资源": item.get("role") or item.get("resource"),
                             "模型": item.get("model"), "互斥类别": item.get("category"), "用量": item.get("quantity"), "单位": item.get("unit"),
                             "单价": item.get("unit_price", "unknown"), "价格版本": item.get("price_version", "unknown"), "币种": item.get("currency", "unknown"),
                             "金额": item.get("cost") if item.get("cost") is not None else "unknown"})
        return table(rows)

    def scope_details(self) -> DataFrame:
        envelope=cached(self,self._act)
        if not envelope.get('ok'):return table(error_rows(envelope))
        detail=ledger_tables(envelope['result']);rows=[]
        for kind in ('scope_rows','price_rows','context_rows'):rows.extend({'分组':kind,**item} for item in detail[kind])
        return table(rows)

    def timing_details(self) -> DataFrame:
        envelope=cached(self,self._act)
        return table(ledger_tables(envelope['result'])['timing_rows']) if envelope.get('ok') else table(error_rows(envelope))

    def unknowns(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        rows = []
        for arm, summary in self._summaries(result):
            rows.append({"工作流": arm, "项目": "总账", "内容": text({key: summary.get(key) for key in ("complete_cost", "total_cost", "currency", "totals_by_currency", "call_count")})})
            rows.append({"工作流": arm, "项目": "时间口径", "内容": text(summary.get("timing", {}))})
            for unknown in summary.get("unknown", []):
                rows.append({"工作流": arm, "项目": "未定项（不是0）", "内容": text(unknown)})
        if "baseline" in result:
            rows.append({"工作流": "comparison", "项目": "差额 / 条件 / 质量", "内容": text({key: result.get(key) for key in ("delta_cost", "delta_cost_reason", "delta_wall_seconds", "controlled_comparison", "controlled_terms", "quality")})})
        return table(rows)
